<script setup>import{Head,Link,router,usePage}from'@inertiajs/vue3';import{ref}from'vue';const p=defineProps({status:String,invitation:Object,authenticated:Boolean,emailMatches:Boolean}),busy=ref(false),page=usePage();function accept(){busy.value=true;router.post(`${page.url}/accept`,{},{onFinish:()=>busy.value=false})}function decline(){router.post(`${page.url}/decline`)}</script>
<template><Head title="Team invitation"/><main class="min-h-screen bg-ink px-5 py-12 text-white"><section class="lp-card mx-auto max-w-xl p-8 text-ink"><p class="font-display text-2xl font-bold text-indigo">LensPic</p><template v-if="status==='valid'"><p class="mt-8 text-xs font-bold uppercase tracking-widest text-slate-400">Secure team invitation</p><h1 class="mt-3 text-3xl font-bold">Join {{invitation.studio}}</h1><p class="mt-3 text-slate-600">You were invited as {{invitation.role}}. This invitation is only valid for {{invitation.email}} and expires {{new Date(invitation.expires_at).toLocaleString()}}.</p><div class="mt-7 space-y-3"><template v-if="authenticated"><button v-if="emailMatches" class="btn-primary w-full" :disabled="busy" @click="accept">{{busy?'Accepting…':'Accept Invitation'}}</button><p v-else class="rounded-xl bg-rose-50 p-4 text-sm text-rose-800">Sign in with the invited email address to accept.</p></template><template v-else><Link href="/login" class="btn-primary block text-center">Sign in to accept</Link><Link href="/register" class="btn-secondary block text-center">Create an individual account</Link></template><button class="btn-muted w-full" @click="decline">Decline</button></div></template><template v-else><h1 class="mt-8 text-3xl font-bold capitalize">Invitation {{status}}</h1><p class="mt-3 text-slate-600">This team invitation can no longer be accepted. Ask the studio owner for a new invitation.</p><Link href="/" class="btn-secondary mt-7">Return to LensPic</Link></template></section></main></template>
